import React from 'react';
import './Pages.css';

function News({ lang }) {
  return (
    <div className="page">
      {/* Тег h1 — «Скидка 20% на латте» */}
      <h1>
        {lang === 'ru'
          ? 'Скидка 20% на латте'
          : '20% discount on latte'}
      </h1>

      {/* Тег p — «Только в выходные дни» */}
      <p>
        {lang === 'ru'
          ? 'Только в выходные дни'
          : 'Only on weekends'}
      </p>

      {/* Тег p — «При предъявлении купона» */}
      <p>
        {lang === 'ru'
          ? 'При предъявлении купона'
          : 'Upon presentation of the coupon'}
      </p>

      {/* Тег h2 — «Акция месяца» */}
      <h2>
        {lang === 'ru'
          ? 'Акция месяца'
          : 'Monthly promotion'}
      </h2>

      {/* Тег p — «Второй капучино в подарок при покупке двух круассанов» */}
      <p>
        {lang === 'ru'
          ? 'Второй капучино в подарок при покупке двух круассанов'
          : 'Second cappuccino free with purchase of two croissants'}
      </p>
    </div>
  );
}

export default News;
